---NORMALIZE---
_hb_ot_shape_normalize (const hb_ot_shape_plan_t *plan,
                        hb_buffer_t *buffer,
                        hb_font_t *font)
{
  if (unlikely (!buffer->len)) return;

  _hb_buffer_assert_unicode_vars (buffer);

  hb_ot_shape_normalization_mode_t mode = plan->shaper->normalization_preference;
  const hb_ot_shape_normalize_context_t c = {
    plan,
    buffer,
    font,
    buffer->unicode,
    plan->shaper->decompose ? plan->shaper->decompose : decompose_unicode,
    plan->shaper->compose   ? plan->shaper->compose   : compose_unicode
  };

  bool always_short_circuit = mode == HB_OT_SHAPE_NORMALIZATION_MODE_NONE;
  bool might_short_circuit = always_short_circuit ||
                             (mode != HB_OT_SHAPE_NORMALIZATION_MODE_DECOMPOSED &&
                              mode != HB_OT_SHAPE_NORMALIZATION_MODE_COMPOSED_DIACRITICS_NO_SHORT_CIRCUIT);
  unsigned int count;

  /* We do a fairly straightforward yet custom normalization process in three
   * separate rounds: decompose, reorder, recompose (if desired).  Currently
   * this makes two buffer swaps.  We can make it faster by moving the last
   * two rounds into the inner loop for the first round, but it's more readable
   * this way. */


  /* First round, decompose */

  buffer->clear_output ();
  count = buffer->len;
  for (buffer->idx = 0; buffer->idx < count && !buffer->in_error;)
  {
    unsigned int end;
    for (end = buffer->idx + 1; end < count; end++)
      if (likely (!HB_UNICODE_GENERAL_CATEGORY_IS_MARK (_hb_glyph_info_get_general_category (&buffer->info[end]))))
        break;

    decompose_cluster (&c, end, might_short_circuit, always_short_circuit);
  }
  buffer->swap_buffers ();


  /* Second round, reorder (inplace) */

  count = buffer->len;
  for (unsigned int i = 0; i < count; i++)
  {
    if (_hb_glyph_info_get_modified_combining_class (&buffer->info[i]) == 0)
      continue;

    unsigned int end;
    for (end = i + 1; end < count; end++)
      if (_hb_glyph_info_get_modified_combining_class (&buffer->info[end]) == 0)
        break;

    /* We are going to do a O(n^2).  Only do this if the sequence is short,
     * but not too short ;). */
    if (end - i < 2 || end - i > HB_OT_SHAPE_COMPLEX_MAX_COMBINING_MARKS) {
      i = end;
      continue;
    }

    buffer->sort (i, end, compare_combining_class);

    if (plan->shaper->reorder_marks)
      plan->shaper->reorder_marks (plan, buffer, i, end);

    i = end;
  }


  if (mode == HB_OT_SHAPE_NORMALIZATION_MODE_NONE ||
      mode == HB_OT_SHAPE_NORMALIZATION_MODE_DECOMPOSED)
    return;

  /* Third round, recompose */

  /* As noted in the comment earlier, we don't try to combine
   * ccc=0 chars with their previous Starter. */

  buffer->clear_output ();
  count = buffer->len;
  unsigned int starter = 0;
  bool combine = true;
  buffer->next_glyph ();
  while (buffer->idx < count && !buffer->in_error)
  {
    hb_codepoint_t composed, glyph;
    if (combine &&
        /* We don't try to compose a non-mark character with it's preceding starter.
         * This is both an optimization to avoid trying to compose every two neighboring
         * glyphs in most scripts AND a desired feature for Hangul.  Apparently Hangul
         * fonts are not designed to mix-and-match pre-composed syllables and Jamo. */
        HB_UNICODE_GENERAL_CATEGORY_IS_MARK (_hb_glyph_info_get_general_category (&buffer->cur())))
    {
      if (/* If there's anything between the starter and this char, they should have CCC
           * smaller than this character's. */
          (starter == buffer->out_len - 1 ||
           info_cc (buffer->prev()) < info_cc (buffer->cur())) &&
          /* And compose. */
          c.compose (&c,
                     buffer->out_info[starter].codepoint,
                     buffer->cur().codepoint,
                     &composed) &&
          /* And the font has glyph for the composite. */
          font->get_nominal_glyph (composed, &glyph))
      {
        /* Composes. */
        buffer->next_glyph (); /* Copy to out-buffer. */
        if (unlikely (buffer->in_error))
          return;
        buffer->merge_out_clusters (starter, buffer->out_len);
        buffer->out_len--; /* Remove the second composable. */
        /* Modify starter and carry on. */
        buffer->out_info[starter].codepoint = composed;
        buffer->out_info[starter].glyph_index() = glyph;
        _hb_glyph_info_set_unicode_props (&buffer->out_info[starter], buffer);

        continue;
      }
      else if (/* We sometimes custom-tailor the sorted order of marks. In that case, stop
                * trying to combine as soon as combining-class drops. */
               starter < buffer->out_len - 1 &&
               info_cc (buffer->prev()) > info_cc (buffer->cur()))
        combine = false;
    }

    /* Blocked, or doesn't compose. */
